def dehydrate_timedelta(value):
    """ Dehydrator for `timedelta` values.

    :param value:
    :type value: timedelta
    :return: dict, representing the timedelta in a dictionary format
    """
    if not isinstance(value, timedelta):
        raise ValueError("Input value must be a timedelta object")
    return {
        'days': value.days,
        'seconds': value.seconds,
        'microseconds': value.microseconds
    }

def dehydrate_time(value):
    """ Dehydrator for `time` values.

    :param value:
    :type value: Time
    :return:
    """
    if value is None:
        return None
    if not isinstance(value, Time):
        raise ValueError("value must be an instance of Time")
    return value.strftime('%H:%M:%S')

def dehydrate_point(value):
    """ Dehydrator for Point data.

    :param value:
    :type value: Point
    :return:
    """
    if not isinstance(value, Point):
        raise ValueError("Input value must be an instance of Point")

    return {
        "lat": value.lat,
        "lon": value.lon,
        "time": value.time.isoformat()
    }

def keys(self):
    """ Return the keys of the record.

    :return: list of key names
    """
    return list(self._keys.keys())

def index(self, key):
    """ Return the index of the given item.

    :param key: a key
    :return: index
    :rtype: int
    """
    try:
        return self._data.index(key)
    except ValueError:
        raise KeyError(f"Key not found: {key}")

def values(self, *keys):
    """
    Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """

    if not keys:
        return list(self._items.values())

    results = []
    for key in keys:
        if isinstance(key, int):
            if key < 0 or key >= len(self._items):
                raise IndexError("Index out of range: {0}".format(key))
            results.append(list(self._items.values())[key])
        elif isinstance(key, str):
            if key not in self._items:
                raise KeyError("Key not found: {0}".format(key))
            results.append(self._items[key])
        else:
            raise TypeError("Invalid key type: {0}".format(type(key).__name__))

    return results

def data(self, *keys):
    """
    Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    result = {}
    if not keys:
        for key, value in self._record.items():
            result[key] = value
    else:
        for key in keys:
            if isinstance(key, int):
                if key < 0 or key >= len(self._record):
                    raise IndexError("Out-of-bounds index specified")
                result[self._record.keys()[key]] = self._record.values()[key]
            elif isinstance(key, str):
                if key not in self._record:
                    result[key] = None
                else:
                    result[key] = self._record[key]
            else:
                raise TypeError("Invalid key type")
    return result

def pop_u16(self):
    """
    Remove the last two bytes of data, returning them as a big-endian
    16-bit unsigned integer.
    """
    if len(self.data) < 2:
        raise ValueError("Not enough data to pop a 16-bit unsigned integer")
    value = self.data[-2:]  # Get the last two bytes
    self.data = self.data[:-2]  # Remove the last two bytes
    return int.from_bytes(value, byteorder='big', signed=False)

def round_half_to_even(n):
    """
    Round half to even, also known as "bankers' rounding".

    :param n: The number to round.
    :return: The rounded number.
    """
    if not isinstance(n, (int, float)):
        raise ValueError("Input must be a number")

    if n % 1 == 0.5:
        return int(n) + (1 if n > 0 else -1)
    else:
        return round(n)

def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass.
    """

    if not all(isinstance(field, tuple) and len(field) == 2 for field in fields):
        raise ValueError("fields must be a list of (name, type) tuples")

    if not all(isinstance(field[0], str) and isinstance(field[1], type) for field in fields):
        raise ValueError("each field must be a tuple of a string and a type")

    if not isinstance(srid_map, dict):
        raise ValueError("srid_map must be a dictionary")

    class PointSubclass:
        __slots__ = fields + ('srid',)

        def __init__(self, *args, srid=None, **kwargs):
            if len(args) != len(fields):
                raise ValueError(f"Expected {len(fields)} arguments, got {len(args)}")
            for field, value in zip(fields, args):
                setattr(self, field[0], value)
            if srid is not None:
                if srid not in srid_map:
                    raise ValueError(f"Invalid SRID: {srid}")
                self.srid = srid_map[srid]
            else:
                self.srid = None

        def __repr__(self):
            args = [f"{field[0]}={getattr(self, field[0])!r}" for field in fields]
            if self.srid is not None:
                args.append(f"srid={self.srid!r}")
            return f"{name}({', '.join(args)})"

    return PointSubclass

import warnings

import functools

def deprecated(message):
    """ Decorator for deprecating functions and methods.

    ::

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass

    """
    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            warnings.warn(message, category=DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)
        return wrapper
    return decorator

def _inline_r_setup(code: str) -> str:
    """
    Some behaviour of R cannot be configured via env variables, but can
    only be configured via R options once R has started. These are set here.
    """
    r_options = {
        "stringsAsFactors": False,
        "max.print": 10000,
        "width": 120
    }

    for option, value in r_options.items():
        code = f"options({option} = {value})\n{code}"

    return code

