from collections import OrderedDict

def mru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Most Recently Used (MRU)
    algorithm.
    """
    def decorator(func):
        if maxsize is None:
            cache = OrderedDict()
        else:
            cache = OrderedDict()

        def wrapper(*args, **kwargs):
            key = (args, tuple(kwargs.items())) if typed else (args, frozenset(kwargs.items()))
            if key in cache:
                cache.move_to_end(key)
            elif len(cache) >= maxsize:
                cache.popitem(last=False)
            result = func(*args, **kwargs)
            cache[key] = result
            return result

        return wraps(func)(wrapper)

    return decorator

from functools import wraps, lru_cache as _lru_cache

from collections.abc import Hashable

def lru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Recently Used (LRU)
    algorithm.

    """
    def decorator(func):
        if not isinstance(func, Hashable):
            raise TypeError('The function to be cached must be hashable')

        return _lru_cache(maxsize=maxsize, typed=typed)(func)

    return decorator

def popitem(self):
    """Remove and return the `(key, value)` pair first inserted."""
    try:
        key, value = self._data.popitem(last=False)
        return (key, value)
    except KeyError:
        raise KeyError('dictionary is empty')

def setdefault(self, key, default=None):
    """
    D.setdefault(k[,d]) -> D.get(k,d), also set D[k]=d if k not in D
    """
    if key in self:
        return self[key]
    else:
        self[key] = default
        return default

def get(self, key, default=None):
    """
    D.get(k[,d]) -> D[k] if k in D, else d.  d defaults to None.
    """
    return self.__getitem__(key, default)

def cachedmethod(cache, key=hashkey, lock=None):
    """Decorator to wrap a class or instance method with a memoizing
    callable that saves results in a cache.

    """
    def decorator(method):
        if lock is None:
            def wrapper(self, *args, **kwargs):
                c = cache(self)
                if c is None:
                    return method(self, *args, **kwargs)
                k = key(*args, **kwargs)
                try:
                    return c[k]
                except KeyError:
                    pass  # key not found
                v = method(self, *args, **kwargs)
                try:
                    c[k] = v
                except ValueError:
                    pass  # value too large
                return v
        else:
            def wrapper(self, *args, **kwargs):
                c = cache(self)
                if c is None:
                    return method(self, *args, **kwargs)
                k = key(*args, **kwargs)
                try:
                    with lock(self):
                        return c[k]
                except KeyError:
                    pass  # key not found
                v = method(self, *args, **kwargs)
                try:
                    with lock(self):
                        c[k] = v
                except ValueError:
                    pass  # value too large
                return v
        return _update_wrapper(wrapper, method)
    return decorator

def minimalBases(classes):
    """
    Reduce a list of base classes to its ordered minimum equivalent
    """
    if not classes:
        return []

    # Create a dictionary to store the base classes and their dependencies
    base_dict = {cls: set(cls.__bases__) for cls in classes}

    # Find the minimal set of base classes
    minimal = set()
    for cls in classes:
        if not any(base in minimal for base in base_dict[cls]):
            minimal.add(cls)

    # Sort the minimal set of base classes
    minimal = sorted(minimal, key=lambda x: classes.index(x))

    return minimal

