def reset(self):
    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    self.context = {}
    if hasattr(self, 'initial_value'):
        self.bins = [self.initial_value] * self.num_bins
    elif hasattr(self, 'make_bins'):
        self.bins = self.make_bins()
    else:
        raise AttributeError("Histogram not properly initialized with initial_value or make_bins method.")

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    if not isinstance(seq, (list, tuple)):
        return False

    for item in seq:
        if isinstance(item, FillRequest):
            return True
        elif isinstance(item, (list, tuple)):
            if is_fill_request_seq(item):
                return True

    return False

def is_fill_request_el(obj):
    """Object contains executable methods 'fill' and 'request'."""
    return hasattr(obj, 'fill') and callable(obj.fill) and hasattr(obj, 'request') and callable(obj.request)

def is_run_el(obj):
    """Object contains executable method 'run'."""
