def absorb(self, args):
    """
    Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    def apply_absorption(expr):
        if isinstance(expr, tuple):
            if expr[0] == 'and':
                if expr[1] == expr[2]:
                    return expr[1]
                elif expr[1] == ('or', expr[0], expr[2]):
                    return expr[0]
            elif expr[0] == 'or':
                if expr[1] == expr[2]:
                    return expr[1]
                elif expr[1] == ('and', expr[0], expr[2]):
                    return expr[0]
        return expr

    def apply_negative_absorption(expr):
        if isinstance(expr, tuple):
            if expr[0] == 'and':
                if expr[1] == ('not', expr[0]):
                    return expr[2]
                elif expr[2] == ('not', expr[0]):
                    return expr[1]
            elif expr[0] == 'or':
                if expr[1] == ('not', expr[0]):
                    return expr[2]
                elif expr[2] == ('not', expr[0]):
                    return expr[1]
        return expr

    new_args = []
    for arg in args:
        new_arg = apply_absorption(arg)
        new_arg = apply_negative_absorption(new_arg)
        new_args.append(new_arg)
    return new_args

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    def inner_func(*args, **kwargs):
        if PY3:
            return namefunc(*args, **kwargs)
        else:
            return namefunc(*args, **kwargs).encode()
    return inner_func

