def render(pieces, style):
    """Render the given version pieces into the requested style."""

    if not pieces:
        raise ValueError("No pieces provided for rendering")

    if style not in ['html', 'json', 'xml']:
        raise ValueError("Unsupported style: {0}".format(style))

    if style == 'html':
        return render_html(pieces)
    elif style == 'json':
        return render_json(pieces)
    elif style == 'xml':
        return render_xml(pieces)

def render_html(pieces):
    """Render pieces as HTML."""
    return '<div>' + ''.join(pieces) + '</div>'

def render_json(pieces):
    """Render pieces as JSON."""
    import json
    return json.dumps(pieces)

def render_xml(pieces):
    """Render pieces as XML."""
    from xml.etree.ElementTree import Element, tostring
    root = Element('root')
    for piece in pieces:
        child = Element('piece')
        child.text = piece
        root.append(child)
    return tostring(root, encoding='unicode')

def plus_or_dot(pieces):
    """Return a + if we don't already have one, else return a ."""

    if '+' in pieces:
        return '.'
    else:
        return '+'

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""

    import subprocess

    if not isinstance(commands, list):
        commands = [commands]

    if not isinstance(args, list):
        args = [args]

    for command in commands:
        try:
            if verbose:
                print(f"Running command: {' '.join(command + args)}")

            if hide_stderr:
                output = subprocess.check_output(command + args, cwd=cwd, stderr=subprocess.STDOUT, env=env)
            else:
                output = subprocess.check_output(command + args, cwd=cwd, env=env)

            if verbose:
                print(f"Command output: {output.decode()}")

        except subprocess.CalledProcessError as e:
            if verbose:
                print(f"Command failed with return code {e.returncode}")
                print(f"Command output: {e.output.decode()}")

            if hide_stderr:
                print(f"Command failed with return code {e.returncode}")
                print(f"Command output: {e.output.decode()}")

            raise

