def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if not alphabet:
        raise ValueError("Alphabet cannot be empty")
    if not all(isinstance(char, str) and len(char) == 1 for char in alphabet):
        raise ValueError("Alphabet must contain single characters")
    if number < 0:
        raise ValueError("Number must be non-negative")
    if padding is not None and padding < 0:
        raise ValueError("Padding must be non-negative")

    base = len(alphabet)
    if number == 0:
        return alphabet[0] * (padding if padding is not None else 1)

    result = []
    while number > 0:
        result.append(alphabet[number % base])
        number //= base

    if padding is not None:
        result.extend([alphabet[0]] * (padding - len(result)))

    return ''.join(reversed(result))

def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    seen = set()
    queue = [cls]

    while queue:
        c = queue.pop()
        seen.add(c)

        sc = c.__subclasses__()
        for c in sc:
            if c not in seen:
                queue.append(c)

    return seen

def string_to_int(string: str, alphabet: List[str]) -> int:
    """
    Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    base = len(alphabet)
    inverse_alphabet = {char: idx for idx, char in enumerate(alphabet)}
    number = 0
    for char in string:
        if char not in inverse_alphabet:
            raise ValueError(f"Character '{char}' not found in alphabet")
        number = number * base + inverse_alphabet[char]
    return number

def unquote(name):
    """Remove quote from the given name."""
    if isinstance(name, str):
        if name.startswith('"') and name.endswith('"'):
            return name[1:-1].replace('\\\\', '\\').replace('\\"', '"')
        if name.startswith("'") and name.endswith("'"):
            return name[1:-1].replace("\\'", "'")
    return name

