              (other values reserved)
    """
    if platform == 'this':
        platform = 1 if os.name == 'posix' else 0

    if platform == 1:
        pattern = r'([^\s"]+|"([^"]*)")'
    elif platform == 0:
        pattern = r'([^\s"]+|"([^"]*)")'
    else:
        raise ValueError("Unsupported platform value")

    return re.findall(pattern, s)

import subprocess

from pathlib import PosixPath

from typing import Optional, Union

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    if not os.path.exists(archive_path):
        raise FileNotFoundError(f"Archive not found: {archive_path}")

    if isinstance(tmp_path, str):
        tmp_path = PosixPath(tmp_path)

    if not tmp_path.exists():
        tmp_path.mkdir(parents=True, exist_ok=True)

    if filename is None:
        filename = os.path.basename(archive_path)

    extract_path = tmp_path / filename
    extract_path.parent.mkdir(parents=True, exist_ok=True)

    if archive_path.endswith('.tar.gz'):
        subprocess.run(['tar', '-xzf', archive_path, '-C', extract_path], check=True)
    elif archive_path.endswith('.tar.bz2'):
        subprocess.run(['tar', '-xjf', archive_path, '-C', extract_path], check=True)
    elif archive_path.endswith('.zip'):
        subprocess.run(['unzip', archive_path, '-d', extract_path], check=True)
    else:
        raise ValueError(f"Unsupported archive type: {archive_path}")

    return f"file://{extract_path}"

def addignored(ignored):
    """ Use the git command to obtain the file names, turn it into a list, sort the list for only ignored files, return those files as a single string with each filename separated by a comma."""

    try:
        output, status = subprocess.Popen(['git', 'ls-files', '--exclude-standard'], stdout=subprocess.PIPE).communicate()
        if status != 0:
            raise Exception("Failed to get list of ignored files")

        files = output.decode('utf-8').splitlines()
        ignored_files = [file for file in files if file in ignored]
        ignored_files.sort()

        return ','.join(ignored_files)
    except Exception as e:
        print(f"An error occurred: {e}")
        return None

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None or frequency.lower() == "always":
        return None

    frequency = frequency.strip()
    if not frequency:
        raise ValueError("Invalid frequency string")

    number, unit = frequency.split()
    number = int(number)

    if unit == "seconds":
        return datetime.timedelta(seconds=number)
    elif unit == "minutes":
        return datetime.timedelta(minutes=number)
    elif unit == "hours":
        return datetime.timedelta(hours=number)
    elif unit == "days":
        return datetime.timedelta(days=number)
    elif unit == "weeks":
        return datetime.timedelta(weeks=number)
    elif unit == "months":
        return datetime.timedelta(days=number * 30)  # Approximation
    elif unit == "years":
        return datetime.timedelta(days=number * 365)  # Approximation
    else:
        raise ValueError("Invalid frequency unit")

