def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    """
    config_dict = {}
    log_records = []

    for filename in config_filenames:
        try:
            if filename.endswith('.toml'):
                with open(filename) as fd:
                    raw_config = fd.read()
                config = toml.loads(raw_config)
            elif filename.endswith('.yaml') or filename.endswith('.yml'):
                with open(filename) as fd:
                    raw_config = fd.read()
                config = yaml.safe_load(raw_config)
            else:
                raise ValueError(f"Unsupported file format: {filename}")

            if overrides:
                config.update(overrides)

            if resolve_env:
                config = resolve_environment_variables(config)

            config_dict[filename] = config
        except Exception as e:
            log_record = logging.LogRecord(
                name='load_configurations',
                level=logging.ERROR,
                pathname=filename,
                lineno=0,
                msg=str(e),
                args=(),
                exc_info=None
            )
            log_records.append(log_record)

    return config_dict, log_records

def resolve_environment_variables(config):
    """
    Recursively resolve environment variables in the configuration dictionary.
    """
    for key, value in config.items():
        if isinstance(value, dict):
            resolve_environment_variables(value)
        elif isinstance(value, str) and value.startswith('${'):
            env_var = value[2:-1]
            if env_var in os.environ:
                config[key] = os.environ[env_var]
    return config

def from_raw_values(cls, values):
    """Create a Bookmarks object from a list of raw bookmark string values.

    You should not need to use this method unless you want to deserialize
    bookmarks.

    :param values: ASCII string values (raw bookmarks)
    :type values: Iterable[str]
    """
    bookmarks = []
    for value in values:
        try:
            bookmark = cls(value)
            bookmarks.append(bookmark)
        except ValueError as e:
            print(f"Invalid bookmark value: {value}. Error: {e}")
    return cls(bookmarks)

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    if isinstance(seq, (list, tuple)):
        return seq, type(seq)
    elif hasattr(seq, '__iter__'):
        return list(seq), type(seq)
    else:
        return seq, type(seq)

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    if not isinstance(iface, type):
        raise TypeError("iface must be a type")
    if not isinstance(candidate, type):
        raise TypeError("candidate must be a type")

    if tentative:
        return iface <= candidate
    else:
        return iface <= candidate and all(hasattr(candidate, attr) for attr in iface.__dict__)

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""

    if explicit_mc is not None:
        return explicit_mc

    for base in bases:
        if hasattr(base, '__metaclass__'):
            return base.__metaclass__

    if not bases:
        return type

    return bases[0].__class__

def pop(self, key, default=__marker):
    """
    D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
    If key is not found, d is returned if given, otherwise KeyError is raised.
    """
    if key not in self:
        if default is not __marker:
            return default
        raise KeyError(key)
    return self._data.pop(key)

def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    if not self._cache:
        raise KeyError('cache is empty')
    key, value = self._cache.popitem(last=False)
    return (key, value)

def popitem(self):
    """Remove and return the `(key, value)` pair most recently used."""
    try:
        key = self._cache.popitem(last=False)[0]
        value = self._data.pop(key)
        return (key, value)
    except KeyError:
        raise KeyError('cache is empty')

import random

def popitem(self):
    """Remove and return a random `(key, value)` pair."""
    if not self:
        raise KeyError('dictionary is empty')
    key = random.choice(list(self.keys()))
    value = self.pop(key)
    return (key, value)

def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    # Private encrypted JSON payload
    try:
        data = json.loads(decode_if_bytes(request.body))
        if "encrypted_magic_envelope" in data:
            return True
    except Exception:
        pass
    # Public XML payload
    try:
        xml = etree.fromstring(encode_if_text(request.body))
        if xml.tag == MAGIC_ENV_TAG:
            return True
    except Exception:
        pass
    return False

def identify_request(request: RequestType) -> bool:
    """
    Try to identify whether this is a Matrix request
    """
    if not request:
        return False

    # Check for common Matrix headers
    if 'Matrix-User' in request.headers or 'Authorization' in request.headers:
        return True

    # Check for common Matrix paths
    if '/_matrix' in request.path:
        return True

    return False

def format_dt(dt):
    """
    Format a datetime in the way that D* nodes expect.
    """
    if not isinstance(dt, datetime):
        raise ValueError("Input must be a datetime object")
    return dt.strftime("%Y-%m-%dT%H:%M:%S")

def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""

    # Check if the tag is not empty
    if not tag:
        return False

    # Check if the tag contains only valid characters
    if not tag.isalnum() and not tag.startswith('_'):
        return False

    # Check if the tag starts with a letter or underscore
    if not tag[0].isalpha() and not tag[0] == '_':
        return False

    return True

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    children_dict = {}
    for child in node:
        children_dict[child.tag] = child
    return children_dict

def get_nodeinfo_well_known_document(url, document_path=None):
    """
