def validate_from_file(cls, yaml_file=None):
    """Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """
    if yaml_file is None:
        raise ValueError("yaml_file argument must be supplied")

    try:
        with open(yaml_file, 'r') as file:
            data = yaml.safe_load(file)

        # Assuming there is a method to validate the data against a schema
        cls.validate_data(data)

        return data

    except FileNotFoundError:
        raise IRValidatorException(f"The file {yaml_file} does not exist.")

    except yaml.YAMLError as e:
        raise IRValidatorException(f"Error parsing YAML file {yaml_file}: {e}")

    except Exception as e:
        raise IRValidatorException(f"An unexpected error occurred: {e}")

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    include_directives = parser_dict.get('include', {})
    for key, value in include_directives.items():
        if isinstance(value, dict):
            self._include_groups(value)
        elif isinstance(value, str):
            with open(value, 'r') as file:
                included_dict = yaml.safe_load(file)
                parser_dict[key] = included_dict
        else:
            raise ValueError(f"Invalid value type for include directive: {type(value)}")

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources. """
    defaults = {}
    for arg in self.args:
        if not isinstance(arg, _BaseOpt):
            raise ValueError('Unable to resolve default for non-Option type')

        # if there is a default set, add it to the defaults dict
        if not isinstance(arg.default, NoDefault):
            defaults[arg.name] = arg.default

        # if we have a dict option, build the defaults for its scheme.
        # if any defaults exist, use them.
        if isinstance(arg, DictOption):
            if arg.scheme:
                b = arg.scheme.get_spec_defaults()
                if b:
                    defaults[arg.name] = b
    return defaults

