def validate_arg_deprecation(self, cli_args, answer_file_args):
    """Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    deprecated_args = {
        'old_arg1': 'new_arg1',
        'old_arg2': 'new_arg2',
        # Add more deprecated arguments as needed
    }

    for old_arg, new_arg in deprecated_args.items():
        if old_arg in cli_args:
            print(f"Warning: '{old_arg}' is deprecated. Use '{new_arg}' instead.")
            cli_args[new_arg] = cli_args.pop(old_arg)
        if old_arg in answer_file_args:
            print(f"Warning: '{old_arg}' is deprecated. Use '{new_arg}' instead.")
            answer_file_args[new_arg] = answer_file_args.pop(old_arg)

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    if command_name not in self.command_specs:
        raise ValueError(f"Command '{command_name}' not found")

    command_spec = self.command_specs[command_name]

    if argument_name not in command_spec.arguments:
        raise ValueError(f"Argument '{argument_name}' not found for command '{command_name}'")

    return command_spec.arguments[argument_name]

def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, silenced argument names
    """
    silenced_args = []
    for arg in args:
        if arg.startswith('-'):
            silenced_args.append(arg)
    return silenced_args

def validate_requires_args(self, args):
    """
    Check if all the required arguments have been provided.
    """
    required_args = {'username', 'password', 'email'}
    missing_args = required_args - set(args)
    if missing_args:
        raise ValueError(f"Missing required arguments: {', '.join(missing_args)}")

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    if not isinstance(args, dict):
        raise TypeError("args must be a dictionary")

    for arg_name, arg_value in args.items():
        if not isinstance(arg_value, str):
            raise TypeError(f"Value of argument '{arg_name}' must be a string")

        if len(arg_value) > 100:
            raise ValueError(f"Value of argument '{arg_name}' is longer than 100 characters")

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    for arg_name, arg_value in args.items():
        if arg_name in self.choices:
            if arg_value not in self.choices[arg_name]:
                raise ValueError(f"Invalid value for argument '{arg_name}': {arg_value}. Available choices are {self.choices[arg_name]}")

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """

    if not args:
        raise ValueError("No arguments provided")

    min_val = getattr(self, 'min_value', None)
    max_val = getattr(self, 'max_value', None)

    if min_val is None and max_val is None:
        raise ValueError("Neither min_value nor max_value is set")

    for arg in args:
        if min_val is not None and arg < min_val:
            raise ValueError(f"Argument {arg} is less than the minimum value {min_val}")
        if max_val is not None and arg > max_val:
            raise ValueError(f"Argument {arg} is greater than the maximum value {max_val}")

    return args

def get_nested_custom_and_control_args(self, args):
    """
    Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    control_args = {}
    nested_args = {}
    custom_args = {}

    for key, value in args.items():
        if key.startswith('control_'):
            control_args[key] = value
        elif key.startswith('nested_'):
            nested_args[key] = value
        elif key.startswith('custom_'):
            custom_args[key] = value
        else:
            nested_args[key] = value

    return control_args, nested_args

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if extra_vars is None:
        return vars_dict

    for var in extra_vars:
        if isinstance(var, dict):
            vars_dict.update(var)
        elif isinstance(var, list):
            for sub_var in var:
                if isinstance(sub_var, dict):
                    vars_dict.update(sub_var)
                else:
                    raise ValueError("Invalid type in extra_vars list")
        else:
            raise ValueError("Invalid type in extra_vars list")

    return vars_dict

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    for key, value in values_dict.items():
        if key == 'port':
            values_dict[key] = int(value)
        elif key == 'host':
            values_dict[key] = str(value)
        elif key == 'blotter':
            values_dict[key] = str(value)
        elif key == 'nopass':
            values_dict[key] = bool(value)
    return values_dict

import os

import json

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    if not os.path.exists(plugin_dir):
        raise FileNotFoundError(f"Plugin directory {plugin_dir} does not exist")

    spec_file_path = os.path.join(plugin_dir, 'spec.json')
    if not os.path.exists(spec_file_path):
        raise FileNotFoundError(f"Plugin spec file {spec_file_path} does not exist")

    with open(spec_file_path, 'r') as file:
        spec_data = json.load(file)

    def flatten_dict(d, parent_key='', sep='_'):
        items = []
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.extend(flatten_dict(v, new_key, sep=sep).items())
            else:
                items.append((new_key, v))
        return dict(items)

    return flatten_dict(spec_data)

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    if 'CONFIG_PATH' not in os.environ:
        os.environ['CONFIG_PATH'] = '/path/to/default/config'
